def validate_outcome(row,root=ROOT,pins=None,*,allow_private=False,data_root=None):
 row=_row(row);identifier=row['id'];require(digest(identifier) and row['category'] in ('scientific_diagram','poster') and row['format'] in FORMATS,'invalid_visual_original_scope');require(digest(row['source_code_hash']) and digest(row['source_image_hash']),'invalid_visual_original_digests');evidence=json.loads(row['record']) if isinstance(row['record'],str) else copy.deepcopy(row['record']);require(isinstance(evidence,dict),'visual_negative_evidence_not_object');markers=[k for k in evidence if any(k.startswith(prefix) for prefix in ('visual_failure_terminal_outcome_v','svg_program_terminal_outcome_v','program_terminal_outcome_v'))];require(markers==[MARKER],'unknown_missing_or_mixed_visual_terminal_marker');require((evidence.get('id'),evidence.get('source_code_sha256'),evidence.get('source_image_sha256'))==(identifier,row['source_code_hash'],row['source_image_hash']),'visual_negative_original_source_mismatch');marker=evidence[MARKER];require(isinstance(marker,dict) and marker.get('policy')==POLICY,'visual_marker_policy_mismatch');receipt=marker['decision'];document=_read(root,receipt,identifier);decision_root=Path(root).resolve();require(document.get('decision_root')==str(decision_root),'visual_decision_root_mismatch');private=document.get('private_validation_only');require(isinstance(private,bool),'visual_private_mode_missing');data=Path(data_root if data_root is not None else root).resolve();require(document.get('data_root')==str(data),'visual_data_root_mismatch');require(not private or allow_private is True and data_root is not None and decision_root.is_relative_to(data/'conversion/prototype/visual_failure_terminal_private_v1') and decision_root!=(data/'conversion/prototype/visual_failure_terminal_private_v1'),'visual_private_decision_not_explicitly_allowed');require(private or data==decision_root,'visual_production_decision_root_mismatch');expected=_expected_pins(data,pins);require(type(document.get('version')) is int and document['version']==1 and document.get('id')==identifier and document.get('writer_policy')==POLICY,'visual_document_author_policy_or_version_mismatch')
 for key in AUTHORS:require(document.get(key)==expected[key],'visual_frozen_author_sha_mismatch:'+key)
 nonce=document.get('commit_nonce');require(isinstance(nonce,str) and re.fullmatch('[0-9a-f]{32}',nonce) and nonce==receipt.get('commit_nonce')==marker.get('commit_nonce'),'visual_commit_nonce_mismatch');require(isinstance(document.get('created_at'),str) and document['created_at'] and document['created_at']==receipt.get('created_at'),'visual_creation_timestamp_mismatch');require(document.get('accepted') is False and document.get('deterministic_recovery_permitted') is True and document.get('abandonment_is_not_conversion_success') is True and type(document.get('new_model_calls')) is int and document['new_model_calls']==0,'visual_nonsuccess_or_rescue_contract_missing');plan=document['plan'];_plan_checks(plan,row);require(sha(canonical(plan))==document.get('plan_sha256')==receipt['plan_sha256'],'visual_plan_digest_mismatch');_source_snapshot(document,plan,row);require(plan['registry_snapshot_sha256']==sha(canonical([document['prior_outcome'][k] for k in REGISTRY_COLUMNS])),'visual_prior_registry_snapshot_digest_mismatch');config=document['reviewed_config'];require(Path(config['root']).resolve()==data and identifier not in config['research_reserved_ids'] and identifier not in config['authorized_model_ids'],'visual_reserved_research_or_model_original');require(isinstance(document.get('file_witnesses'),dict) and document['file_witnesses'],'visual_file_preparation_missing');require(isinstance(plan.get('pins'),dict) and plan['pins']==config['pins'],'visual_plan_reviewed_pin_set_mismatch');
 for key,name in AUTHORS.items():require([v for p,v in config['pins'].items() if Path(p).name==name]==[expected[key]],'visual_reviewed_author_pin_mismatch:'+key)
 cache=_artifact_bytes(plan,data);fresh,ob,native,png=_fresh_evidence(plan,document,cache,data);_supervisor_evidence(plan,document,cache,data,fresh,ob,native,png);reason,exact=_evidence(plan,receipt);require(row['reason']==reason and canonical(evidence)==canonical(exact),'visual_outcome_differs_from_exact_decision');return {'id':identifier,'kind':'visual_failure_terminal_v1','receipt_verified':True,'source_identity_verified':True,'decision':receipt,'commit_nonce':nonce,**expected,'accepted':False,'deterministic_recovery_permitted':True,'abandonment_is_not_conversion_success':True,'source_semantically_unsupported':False,'native_editing':{'state':'not_reached','ok':None}}

def manifest_row(row,root=ROOT,pins=None,*,allow_private=False,data_root=None):
 row=_row(row);validate_outcome(row,root,pins,allow_private=allow_private,data_root=data_root);evidence=json.loads(row['record']) if isinstance(row['record'],str) else copy.deepcopy(row['record']);return {'id':row['id'],'category':row['category'],'source_format':row['format'],'status':'abandoned','reason':row['reason'],'source_code_sha256':row['source_code_hash'],'source_image_sha256':row['source_image_hash'],'decision':evidence}
